import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const shown=[], history=[], queue=[], telemetry=[];
let resolveOld;
const feed=createProgressFeed({initialPacket: 'initial', decode: p => p === 'old' ? new Promise(r => {resolveOld=r;}) : p});
const stopTelemetry=collectProgressTelemetry(feed, x => telemetry.push(x));
const ws=createTransferWorkspace({transport(){},onCancel(){},record:x=>queue.push(x),showQueued(){},recordProgress:x=>history.push(x.frame),showProgress:x=>shown.push(x.frame)});
ws.select({id:'a',progressFeed:feed});
assert.deepEqual(shown,['initial']);
assert.deepEqual(telemetry,[]);
feed.emit('old'); feed.emit('new'); resolveOld('older');
await Promise.resolve();
assert.deepEqual(shown,['initial','new']);
assert.deepEqual(history,['initial','new','older']);
assert.deepEqual(telemetry,['new','older']);
assert.deepEqual(queue,[{fileId:'a',attemptId:1,visitId:1,kind:'select'}]);
ws.dispose(); stopTelemetry();
let second;
const reentrantFeed=createProgressFeed({initialPacket:'boot',onDetach(){}});
const reentrant=createTransferWorkspace({transport(){},onCancel(){},record(){},showQueued(){},recordProgress(){},showProgress(){reentrant.hide();}});
reentrant.select({id:'b',progressFeed:reentrantFeed});
assert.equal(reentrant.snapshot().visitId,null);
reentrantFeed.emit('later');
console.log('progress checks passed');
EOF"

